+        let out = tap_on(name);
+        assert!(out.warnings.is_empty(), "{name}: {:?}", out.warnings);
+        assert!(
+            out.program.lines().any(|l| l.starts_with("G84")),
+            "{name}:\n{}",
+            out.program
+        );
+    }
